function drawBackground(){
 const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#83d8f6');g.addColorStop(.64,'#b5ebf5');g.addColorStop(1,'#e4f6df');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // soft sunshine, distant twinkles
 ctx.save();ctx.globalAlpha=.72;ctx.fillStyle='#fff0b0';ctx.beginPath();ctx.arc(783,113,42,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.14;ctx.beginPath();ctx.arc(783,113,62,0,Math.PI*2);ctx.fill();ctx.restore();
 stars.forEach(s=>{let x=(s.x-camera*.1%W+W)%W;ctx.globalAlpha=s.a*(.7+.3*Math.sin(worldTime*2+s.x));ctx.fillStyle='#fff';ctx.fillRect(x,s.y,s.r,s.r)});ctx.globalAlpha=1;
 // clouds drift with parallax
 for(let i=0;i<8;i++){let x=((i*203-camera*.2+worldTime*5)%(W+180)+W+180)%(W+180)-75,y=79+(i*53)%115;ctx.globalAlpha=.83;roundRect(x,y+12,82,20,10,'#fff');ctx.beginPath();ctx.arc(x+26,y+12,17,Math.PI,0);ctx.arc(x+49,y+7,22,Math.PI,0);ctx.arc(x+68,y+14,13,Math.PI,0);ctx.fillStyle='#fff';ctx.fill()}ctx.globalAlpha=1;
 // far hills
 for(let i=0;i<7;i++){let x=((i*235-camera*.28)%(W+300)+W+300)%(W+300)-120;ctx.fillStyle=i%2?'#a6dfcb':'#9bd8c8';ctx.beginPath();ctx.moveTo(x,390);ctx.quadraticCurveTo(x+95,225+(i%3)*25,x+205,390);ctx.fill();ctx.fillStyle='#d5f0cf';ctx.beginPath();ctx.moveTo(x+69,311);ctx.quadraticCurveTo(x+95,265,x+122,305);ctx.quadraticCurveTo(x+95,292,x+69,311);ctx.fill()}
 // near rolling meadow
 for(let i=0;i<6;i++){let x=((i*290-camera*.43)%(W+350)+W+350)%(W+350)-130;ctx.fillStyle=i%2?'#79c985':'#87d28b';ctx.beginPath();ctx.ellipse(x+130,430,155,66,0,Math.PI,Math.PI*2);ctx.fill()}
 // decorative flowers and tiny trees, world anchored
 for(let i=0;i<34;i++){let wx=i*151+58,sx=wx-camera*.62;if(sx<-40||sx>W+40)continue;let y=GROUND-8; if(i%4===0){rect(sx-3,y-38,6,36,'#508f65');roundRect(sx-19,y-61,38,27,11,'#57a776');roundRect(sx-14,y-75,28,21,10,'#73bc80')}else{rect(sx,y-9,2,9,'#479a62');ctx.fillStyle=i%2?'#fff5b0':'#ffe6c0';ctx.beginPath();ctx.arc(sx,y-11,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f6aa53';ctx.beginPath();ctx.arc(sx,y-11,1.4,0,Math.PI*2);ctx.fill()}}
}
function drawWorld(){
 ctx.save();ctx.translate(-camera,0);
 // ground slabs
 platforms.filter(p=>p.y===GROUND).forEach(p=>{rect(p.x,GROUND,p.w,H-GROUND,'#bd7948');rect(p.x,GROUND,p.w,13,'#68bd61');rect(p.x,GROUND+13,p.w,7,'#8bd275');for(let x=p.x+12;x<p.x+p.w;x+=34){rect(x,GROUND+36,17,3,'#a7663f');rect(x+13,GROUND+65,12,3,'#a7663f');rect(x-5,GROUND+96,20,3,'#a7663f')}for(let x=p.x+8;x<p.x+p.w;x+=48){rect(x,GROUND+22,4,4,'#d8985c')}});
 // blocks
 platforms.filter(p=>p.y<GROUND).forEach(p=>{if(p.type==='question'){let used=p.used;roundRect(p.x,p.y,p.w,44,5,used?'#bd8952':'#f1a53e');roundRect(p.x+3,p.y+3,p.w-6,38,4,used?'#d4aa73':'#ffc95c');ctx.strokeStyle=used?'#aa855a':'#ffe39a';ctx.lineWidth=2;ctx.strokeRect(p.x+4,p.y+4,p.w-8,36);ctx.fillStyle=used?'#987a59':'#fff4cf';ctx.font='900 27px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(used?'·':'?',p.x+p.w/2,p.y+22)}else{roundRect(p.x,p.y,p.w,44,5,'#b8663c');roundRect(p.x+2,p.y+2,p.w-4,40,4,'#d9834b');rect(p.x+2,p.y+20,p.w-4,4,'#b8663c');for(let x=p.x+22;x<p.x+p.w;x+=44){rect(x,p.y+2,4,18,'#b8663c');rect(x-20,p.y+24,4,16,'#b8663c')}rect(p.x+5,p.y+6,p.w-10,3,'#f3aa67')}});
 // collectible stars
 coinItems.forEach(c=>{if(c.got)return;let bob=Math.sin(worldTime*4+c.phase)*4,x=c.x,y=c.y+bob;ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(worldTime*2+c.phase)*.18);ctx.fillStyle='#f69d43';ctx.beginPath();for(let i=0;i<10;i++){let r=i%2?7:13,a=-Math.PI/2+i*Math.PI/5;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath();ctx.fill();ctx.strokeStyle='#ffe298';ctx.lineWidth=2;ctx.stroke();ctx.restore();ctx.fillStyle='#fff2bf';ctx.beginPath();ctx.arc(x-3,y-3,2,0,Math.PI*2);ctx.fill()});
 // roaming mushroom critters
 enemies.forEach(e=>{if(!e.alive)return;let bob=Math.sin(worldTime*8+e.phase)*1.6,x=e.x,y=e.y+bob;ctx.save();ctx.translate(x+e.w/2,y+e.h/2);if(e.dir<0)ctx.scale(-1,1);if(e.stun>0)ctx.rotate(Math.sin(worldTime*30)*.12);ctx.translate(-e.w/2,-e.h/2);
 roundRect(4,17,23,14,7,'#f2d5a0');roundRect(5,22,21,9,5,'#b77746');roundRect(1,6,29,17,9,'#e8665e');roundRect(5,1,21,10,7,'#ff8370');ctx.fillStyle='#fff1d2';ctx.beginPath();ctx.arc(9,12,4,0,Math.PI*2);ctx.arc(22,9,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3b3544';ctx.beginPath();ctx.arc(10,13,1.8,0,Math.PI*2);ctx.arc(22,10,1.8,0,Math.PI*2);ctx.fill();rect(11,26,3,2,'#76513e');rect(22,26,3,2,'#76513e');ctx.restore()});
 // finish flag and goal
 if(LEVEL-camera<W+120){rect(LEVEL-125,GROUND-180,7,180,'#f6ead0');ctx.fillStyle='#fff8e6';ctx.beginPath();ctx.arc(LEVEL-121.5,GROUND-182,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f0a34d';ctx.beginPath();ctx.moveTo(LEVEL-118,GROUND-173);ctx.lineTo(LEVEL-48,GROUND-154);ctx.lineTo(LEVEL-118,GROUND-134);ctx.fill();rect(LEVEL-145,GROUND,47,10,'#a86844')}
 ctx.restore();
}
function drawHero(){
 let x=player.x+player.w/2,y=player.y+player.h/2;ctx.save();ctx.translate(x,y);let angle=player.spin;ctx.rotate(angle);if(player.facing<0)ctx.scale(-1,1);
 let running=Math.abs(player.vx)>35&&player.grounded,phase=player.run;let legSwing=running?Math.sin(phase*17)*8:player.grounded?0:4;let lean=clamp(player.vx/600,-.18,.18);ctx.rotate(lean);
 // shadow when airborne
 if(!player.grounded){ctx.restore();ctx.globalAlpha=.2;ctx.fillStyle='#355d59';ctx.beginPath();ctx.ellipse(player.x+player.w/2,GROUND-2,14+Math.min(12,Math.abs(player.y-GROUND+player.h)*.04),4,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.save();ctx.translate(x,y);ctx.rotate(angle);if(player.facing<0)ctx.scale(-1,1);ctx.rotate(lean)}
 // boots and legs
 roundRect(-13+legSwing*.4,11,12,9,4,'#51404a');roundRect(2-legSwing*.4,11,13,9,4,'#51404a');roundRect(-12+legSwing*.4,8,9,9,3,'#81503d');roundRect(3-legSwing*.4,8,9,9,3,'#81503d');
 // overalls
 roundRect(-11,-9,22,24,7,'#3979ba');roundRect(-7,-12,14,10,4,'#f0a54b');roundRect(-8,0,6,5,2,'#f5cb6b');roundRect(3,0,6,5,2,'#f5cb6b');
 // arms pumping
 let arm=Math.sin(phase*17)*4;roundRect(-17,-8+arm,8,17,4,'#e89b69');roundRect(9,-9-arm,8,16,4,'#e89b69');roundRect(-18,5+arm,9,7,3,'#f0c98e');roundRect(10,4-arm,9,7,3,'#f0c98e');
 // face and hair
 roundRect(-11,-28,22,22,8,'#f4bd86');roundRect(-12,-27,6,15,3,'#804b3b');roundRect(7,-26,5,12,3,'#804b3b');roundRect(-3,-19,3,4,1,'#fff');roundRect(-2,-18,2,3,1,'#304155');roundRect(7,-19,3,4,1,'#fff');roundRect(8,-18,2,3,1,'#304155');roundRect(0,-12,10,4,2,'#9b5549');
 // cap, signature but original silhouette
 roundRect(-13,-34,24,11,5,'#d95d54');roundRect(-15,-28,29,5,3,'#b94c4c');roundRect(0,-32,7,4,2,'#ffe3a2');
 // sparkle on clothing
 ctx.fillStyle='#ffe5a7';ctx.beginPath();ctx.arc(-5,-4,1.4,0,Math.PI*2);ctx.fill();
 ctx.restore();
}

