function update(dt){
 worldTime+=dt;if(state!=='playing'){return}time-=dt;if(time<=0){time=0;finish(false);return}if(toastTime>0){toastTime-=dt;if(toastTime<=0)ui.toast.classList.remove('show')}
 player.invuln=Math.max(0,player.invuln-dt);player.jumpBuffer=Math.max(0,player.jumpBuffer-dt);player.landSquash=Math.max(0,player.landSquash-dt);player.coyote=player.grounded?.1:Math.max(0,player.coyote-dt);
 const dir=(keys.right?1:0)-(keys.left?1:0),max=keys.sprint?365:255,acc=player.grounded?1450:850;
 if(dir){player.vx+=dir*acc*dt;player.vx=clamp(player.vx,-max,max);player.facing=dir}else player.vx*=Math.pow(player.grounded?0.001:0.18,dt);
 if(player.jumpBuffer>0&&(player.grounded||player.coyote>0)){player.jumpBuffer=0;jump()}
 player.x+=player.vx*dt;player.x=clamp(player.x,0,LEVEL+25);let prevBottom=player.y+player.h,prevY=player.y;player.vy+=1750*dt;player.y+=player.vy*dt;player.grounded=false;
 // platform landings
 for(const p of platforms){if(player.x+player.w>p.x&&player.x<p.x+p.w&&prevBottom<=p.y+5&&player.y+player.h>=p.y&&player.vy>=0){player.y=p.y-player.h;player.vy=0;player.grounded=true;if(player.landSquash===0)player.landSquash=.12;if(p.y<GROUND&&p.type==='question'&&!p.used&&prevY>p.y+20){p.used=true;coins++;addScore(100,p.x+p.w/2,p.y-22,'+100');burst(p.x+p.w/2,p.y,'#ffd56f',9)}}
 // bonk question blocks from below
 if(p.y<GROUND&&p.type==='question'&&!p.used&&player.vy<0&&prevY>=p.y+44&&player.y<=p.y+44&&player.x+player.w>p.x&&player.x<p.x+p.w){p.used=true;player.vy=95;coins++;addScore(100,p.x+p.w/2,p.y-18,'+100');burst(p.x+p.w/2,p.y,'#ffcb5d',10)} }
 if(player.grounded){player.coyote=.11;if(player.jumpBuffer>0)jump()}else player.coyote=Math.max(0,player.coyote-dt);
 // flight rotation: gather spin for style, flip when landing on a critter
 if(!player.grounded&&Math.abs(player.vy)>100){player.spinV+=(player.vy<0?1:-1)*dt*3.2;player.spinV=clamp(player.spinV,-7.2,7.2);player.spin+=player.spinV*dt;}
 else if(player.grounded){player.spinV=0;player.spin*=Math.max(0,1-dt*14)}
 player.run+=dt*(Math.abs(player.vx)*.045+2);
