 ctx.save();ctx.translate(-camera,0);particles.forEach(p=>{ctx.globalAlpha=clamp(p.life*1.6,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)});ctx.globalAlpha=1;
 floaters.forEach(f=>{ctx.globalAlpha=clamp(f.life*2,0,1);ctx.font='900 14px system-ui';ctx.textAlign='center';ctx.lineWidth=3;ctx.strokeStyle='#694831';ctx.strokeText(f.text,f.x,f.y);ctx.fillStyle='#fff0b2';ctx.fillText(f.text,f.x,f.y)});ctx.globalAlpha=1;ctx.restore();
 if(!(player.invuln>0&&Math.floor(worldTime*15)%2===0))drawHero();
 let vg=ctx.createLinearGradient(0,0,0,H);vg.addColorStop(.72,'#18375400');vg.addColorStop(1,'#18375417');ctx.fillStyle=vg;ctx.fillRect(0,0,W,H);ctx.restore();
}
function frame(now){let dt=Math.min(.034,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}
updateHud();requestAnimationFrame(frame);
})();
