 function resetGame(){score=0;coins=0;lives=3;time=300;camera=0;particles=[];floaters=[];player.x=82;player.y=GROUND-player.h;player.vx=player.vy=0;player.grounded=true;player.spin=player.spinV=0;player.invuln=0;enemies.forEach(e=>{e.alive=true;e.stun=0});coinItems.forEach(c=>c.got=false);platforms.forEach(p=>{if(p.type==='question')p.used=false});updateHud()}
 function burst(x,y,color,n=12){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=60+Math.random()*220;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-50,life:.45+Math.random()*.55,color,size:2+Math.random()*4})}}
 function loseLife(){if(player.invuln>0||state!=='playing')return;lives--;updateHud();if(lives<=0){finish(false);return}player.x=Math.max(60,player.x-180);player.y=GROUND-110;player.vx=0;player.vy=-110;player.invuln=2;shake=9;showToast('¡UNA VIDA MENOS!')}
 function finish(win){state=win?'won':'over';ui.eyebrow.textContent=win?'¡NIVEL COMPLETADO!':'FIN DE LA AVENTURA';ui.title.textContent=win?'¡Eres una estrella!':'¡A intentarlo otra vez!';ui.text.textContent=win?`Pradera despejada. Conseguíste ${coins} estrellas y ${score} puntos. ¡Qué carrera!`:'Las setas te ganaron esta vez. ¡Vuelve a intentarlo y enlaza tus mortales!';ui.play.textContent=win?'Jugar de nuevo':'Reintentar';ui.overlay.classList.remove('hidden')}
-function jump(){if(state!=='playing')return;if(player.grounded||player.coyote>0){player.vy=-650-(keys.sprint?45:0);player.grounded=false;player.coyote=0;player.spinV=0;player.landSquash=0;burst(player.x+player.w/2,player.y+player.h-2,'#fff0bd',5)}else player.jumpBuffer=.13}
+function jump(){if(state!=='playing')return;if(player.grounded||player.coyote>0){player.vy=-650-(keys.sprint?45:0);player.grounded=false;player.coyote=0;player.spinV=(keys.sprint?9:6.5)*player.facing;player.landSquash=0;burst(player.x+player.w/2,player.y+player.h-2,'#fff0bd',5)}else player.jumpBuffer=.13}
 function handleKey(e,down){let k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','shift','a','d','w'].includes(k))e.preventDefault();if(k==='arrowleft'||k==='a')keys.left=down;if(k==='arrowright'||k==='d')keys.right=down;if(k==='shift')keys.sprint=down;if((k===' '||k==='arrowup'||k==='w')&&down&&!e.repeat)jump()}
 window.addEventListener('keydown',e=>handleKey(e,true));window.addEventListener('keyup',e=>handleKey(e,false));window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
 document.querySelectorAll('.touch-btn').forEach(b=>{const key=b.dataset.key;const set=(v,e)=>{e.preventDefault();if(key==='jump'){if(v)jump()}else keys[key==='left'?'left':'right']=v;b.classList.toggle('down',v)};b.addEventListener('pointerdown',e=>{b.setPointerCapture(e.pointerId);set(true,e)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,e=>set(false,e)))});
 ui.play.addEventListener('click',()=>{if(state==='ready'||state==='won'||state==='over')resetGame();state='playing';ui.overlay.classList.add('hidden');last=performance.now()});

